// One generated-file rule for every caller: a generator's header on the first line or a `.gen.` name. A lookalike that
// is no house marker (a lower-case "Generated by", a header past the first line, a `.generated.` name) is authored.
// The files each generator writes in the real tree carry the marker.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "@orb/testkit/tooling";
import { isGeneratedFile } from "../../../../tooling/src/floor/paths/generated-file.ts";

test("the header after each comment opener and the .gen. infix mark a file; a lookalike does not", () => {
  const cases = [
    { path: "a.ts", head: "// GENERATED by a.build.ts — DO NOT EDIT.\n" },
    { path: "a.css", head: "/* GENERATED by a.build.ts — DO NOT EDIT. */\n" },
    { path: "a.ts", head: "/** GENERATED by a.build.ts — DO NOT EDIT. */\n" },
    { path: "packages/ui/src/tokens/themes.gen.ts", head: "export const x = 1;\n" },
    { path: "a.ts", head: "// Generated by a script.\n" },
    { path: "a.ts", head: "export const x = 1;\n// GENERATED by a.build.ts\n" },
    { path: "packages/a/src/support.generated.ts", head: "export const x = 1;\n" },
    { path: "a.ts", head: "export const generated = 1;\n" },
  ];
  expect(cases.map(({ path, head }) => isGeneratedFile(path, () => head))).toEqual([true, true, true, true, false, false, false, false]);
});

test("every file a house generator writes in the tree reads as generated", ({ repoRoot }) => {
  const written = [
    "packages/ui/src/tokens/index.ts",
    "packages/ui/src/tokens/themes.gen.ts",
    "packages/ui/src/styles/theme.css",
    "packages/kit/src/handle-key/unicode-data.ts",
    "packages/client/owner-css-surface.ts",
    "packages/client/src/styles/appearance-channel.gen.css",
    "packages/plugin-toolchain/src/support.generated.ts",
  ];
  const authored = written.filter((path) => !isGeneratedFile(path, () => readFileSync(join(repoRoot, path), "utf8")));
  expect(authored).toEqual([]);
  // The control: an authored source beside them stays authored.
  expect(isGeneratedFile("packages/kit/src/ids/index.ts", () => readFileSync(join(repoRoot, "packages/kit/src/ids/index.ts"), "utf8"))).toBe(false);
});
